{/* 1. Desktop Layout (hidden md:block) */}
<div className="hidden md:block space-y-2.5 md:space-y-3.5">
    {/* Top Tier: Mandatory Clinical Metadata */}
    <div className="grid grid-cols-1 md:grid-cols-10 gap-3 md:gap-4 xl:gap-6 pb-2.5 md:pb-3 border-b border-slate-100 dark:border-slate-800">
        {/* Patient Selection */}
        <div className="space-y-1.5 md:col-span-3">
            <div className="flex items-center gap-1.5 mb-0.5">
                <User size={13} className="text-slate-400" />
                <Label className="text-[10px] font-bold uppercase tracking-[0.14em] text-slate-400">{t('record.client_identity', 'Client identity')}</Label>
                {selectedPatient && <Check size={11} className="text-emerald-400" />}
            </div>
            {selectedPatient ? (
                <PatientSummaryCard
                    patient={selectedPatient}
                    onReset={() => {
                        setSelectedPatient(null);
                        setPatientInfo({ name: '', dob: '', context: '', customTemplateText: '' });
                        setClioNote(null);
                    }}
                />
            ) : (
                <PatientSelector
                    onSelect={(p) => {
                        setSelectedPatient(p);
                        setPatientInfo(prev => ({
                            ...prev,
                            name: p.full_name,
                            dob: p.dob || ''
                        }));
                    }}
                    onInputChange={(val) => {
                        setPatientInfo(prev => ({ ...prev, name: val }));
                    }}
                    onCreateNew={() => setIsCreateModalOpen(true)}
                />
            )}
        </div>

        {/* Encounter Date & Time */}
        <div className="space-y-1.5 md:col-span-4">
            <div className="flex items-center gap-1.5 mb-0.5">
                <Calendar size={13} className="text-slate-400" />
                <Label className="text-[10px] font-bold uppercase tracking-[0.14em] text-slate-400">{t('record.encounter_info', 'Encounter Info')}</Label>
                {serviceDate && timeIn && <Check size={11} className="text-emerald-400" />}
            </div>
            <div className="flex bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-full shadow-sm transition-all hover:border-slate-350 dark:hover:border-slate-700 focus-within:border-indigo-500/40 focus-within:ring-4 focus-within:ring-indigo-500/5 overflow-hidden mt-0.5 h-10 items-center">
                {/* Date */}
                <div className="flex-[1.0] min-w-[105px] border-r border-slate-100 dark:border-slate-800">
                    <DatePicker 
                        date={serviceDate} 
                        setDate={setServiceDate} 
                        className="h-full rounded-none border-0 shadow-none bg-transparent w-full focus-visible:ring-0 px-2.5 font-medium text-slate-600 dark:text-slate-300 tracking-tight text-xs"
                    />
                </div>
                {/* Time In */}
                <div className="border-r border-slate-100 dark:border-slate-800 h-full flex items-center pr-1">
                    <Popover open={isTimePopoverOpen} onOpenChange={setIsTimePopoverOpen}>
                        <PopoverTrigger asChild>
                            <Button variant="ghost" className="h-full rounded-none hover:bg-slate-100 dark:hover:bg-slate-800 px-2.5 font-semibold text-slate-500 dark:text-slate-300 min-w-[85px] w-auto flex items-center gap-1.5 justify-center transition-colors tracking-tight text-xs">
                                <Clock size={13} className="text-slate-400 dark:text-slate-400 shrink-0" />
                                <span className="text-xs whitespace-nowrap text-slate-600 dark:text-slate-300">{timeIn ? `In: ${timeIn}` : (language === 'es' ? 'Inicio' : 'Start')}</span>
                            </Button>
                        </PopoverTrigger>
                        <PopoverContent className="w-[300px] p-0 rounded-[2.5rem] overflow-hidden border-0 shadow-[0_20px_70px_-10px_rgba(0,0,0,0.15)] ring-1 ring-slate-900/5 bg-white/70 dark:bg-slate-900/70 backdrop-blur-xl" side="bottom" align="center" sideOffset={12}>
                            <div className="flex flex-col items-center">
                                <div className="w-full pt-8 pb-4 text-center">
                                    <span className="font-medium tracking-tight text-slate-800 dark:text-slate-100 text-[18px]">{language === 'es' ? 'Seleccionar hora' : 'Select Time'}</span>
                                    <div className="text-[11px] font-medium text-slate-400 dark:text-slate-500 uppercase tracking-widest mt-1 opacity-80">{language === 'es' ? 'Inicio del encuentro' : 'Encounter Start'}</div>
                                </div>
                                <div className="px-6 pb-6 w-full">
                                    <TimeSpinner 
                                        initialTimeStr={timeIn}
                                        onConfirm={(timeStr) => {
                                            handleTimeInChange(timeStr);
                                            setIsTimePopoverOpen(false);
                                        }} 
                                    />
                                </div>
                            </div>
                        </PopoverContent>
                    </Popover>
                </div>
                {/* Time Out */}
                <div className="border-r border-slate-100 dark:border-slate-800 h-full flex items-center pr-1">
                    <Popover open={isTimeOutPopoverOpen} onOpenChange={setIsTimeOutPopoverOpen}>
                        <PopoverTrigger asChild>
                            <Button variant="ghost" className="h-full rounded-none hover:bg-slate-100 dark:hover:bg-slate-800 px-2.5 font-semibold text-slate-500 dark:text-slate-300 min-w-[85px] w-auto flex items-center gap-1.5 justify-center transition-colors tracking-tight text-xs">
                                <Clock size={13} className="text-slate-400 dark:text-slate-400 shrink-0" />
                                <span className="text-xs whitespace-nowrap text-slate-600 dark:text-slate-300">{timeOut ? `Out: ${timeOut}` : (language === 'es' ? 'Fin' : 'End')}</span>
                            </Button>
                        </PopoverTrigger>
                        <PopoverContent className="w-[300px] p-0 rounded-[2.5rem] overflow-hidden border-0 shadow-[0_20px_70px_-10px_rgba(0,0,0,0.15)] ring-1 ring-slate-900/5 bg-white/70 dark:bg-slate-900/70 backdrop-blur-xl" side="bottom" align="center" sideOffset={12}>
                            <div className="flex flex-col items-center">
                                <div className="w-full pt-8 pb-4 text-center">
                                    <span className="font-medium tracking-tight text-slate-800 dark:text-slate-100 text-[18px]">{language === 'es' ? 'Seleccionar hora' : 'Select Time'}</span>
                                    <div className="text-[11px] font-medium text-slate-400 dark:text-slate-500 uppercase tracking-widest mt-1 opacity-80">{language === 'es' ? 'Fin del encuentro' : 'Encounter End'}</div>
                                </div>
                                <div className="px-6 pb-6 w-full">
                                    <TimeSpinner 
                                        initialTimeStr={timeOut}
                                        onConfirm={(timeStr) => {
                                            handleTimeOutChange(timeStr);
                                            setIsTimeOutPopoverOpen(false);
                                        }} 
                                    />
                                </div>
                            </div>
                        </PopoverContent>
                    </Popover>
                </div>
                {/* Duration in Minutes */}
                <div className="w-[75px] h-full flex items-center px-2 shrink-0">
                    <input 
                        type="number"
                        min="0"
                        autoComplete="off"
                        placeholder={language === 'es' ? "Min." : "Min"}
                        value={durationMin}
                        onChange={(e) => handleDurationMinChange(e.target.value)}
                        style={{ border: 'none', outline: 'none', boxShadow: 'none' }}
                        className="h-full !border-0 focus:!border-0 focus:!border-transparent focus-visible:!border-0 focus-visible:!border-transparent bg-transparent text-slate-700 dark:text-slate-200 font-semibold focus:ring-0 focus:outline-none focus-visible:ring-0 focus-visible:outline-none outline-none text-center text-xs w-full px-1 [appearance:textfield] [&::-webkit-outer-spin-button]:appearance-none [&::-webkit-inner-spin-button]:appearance-none cursor-pointer"
                    />
                </div>
            </div>
        </div>

        {/* Service Provided */}
        <div className="space-y-1.5 md:col-span-3">
            <div className="flex items-center gap-1.5 mb-0.5">
                <ClipboardList size={13} className="text-slate-400" />
                <Label className="text-[10px] font-bold uppercase tracking-[0.14em] text-slate-400">{t('record.service_provided', 'Service Provided')}</Label>
                {selectedSubTemplate && <Check size={11} className="text-emerald-400" />}
            </div>
            <div ref={subTemplateDropdownRef} className="relative mt-0.5">
                <div 
                    onClick={() => setIsDropdownOpen(true)}
                    className={cn(
                        "w-full h-10 flex items-center justify-between px-4 bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-full shadow-sm cursor-text transition-all hover:border-slate-350 dark:hover:border-slate-700 hover:bg-indigo-50/5 dark:hover:bg-indigo-950/5",
                        isDropdownOpen ? "border-indigo-500/40 ring-4 ring-indigo-500/5" : ""
                    )}
                >
                    <div className="flex items-center gap-2 flex-1">
                        <input
                            type="text"
                            style={{ border: 'none', outline: 'none', boxShadow: 'none', background: 'transparent' }}
                            className="w-full h-full !border-0 focus:!border-0 focus:!border-transparent focus-visible:!border-0 focus-visible:!border-transparent bg-transparent focus:bg-transparent active:bg-transparent focus-visible:bg-transparent text-xs font-medium tracking-tight text-slate-700 dark:text-slate-200 placeholder-slate-400 dark:placeholder-slate-500 p-0 focus:ring-0 focus:outline-none focus-visible:ring-0 focus-visible:outline-none outline-none"
                            placeholder="Select encounter type..."
                            value={isDropdownOpen ? subTemplateSearchQuery : selectedSubTemplate}
                            onChange={(e) => {
                                setSubTemplateSearchQuery(e.target.value);
                                setIsDropdownOpen(true);
                            }}
                            onFocus={() => setIsDropdownOpen(true)}
                        />
                    </div>

